INSERT INTO event VALUES(196,5,4,'context.blob',1,1767225796000,'{"payload":{"digest":"f176bf201abf15e0080d9de853f60bb062a32787e41aaab32eb0bee2407de755","value":"{\"delegation\":{\"agents\":[],\"models\":[\"openai/gpt-6.1-sol\",\"openai/gpt-5.6-terra\",\"openai/gpt-6-luna\",\"deepseek/deepseek-flash\",\"deepseek/deepseek-v4-pro\"]},\"sections\":{\"core plugin\":\"For math in responses, use $...$ or \\\\(...\\\\) for inline and $$...$$ or \\\\[...\\\\] for display math. Wrap LaTeX environments like align or gather inside $$...$$ (e.g., $$\\\\begin{align}...\\\\end{align}$$) so they render correctly.\"},\"tools\":[\"script\",\"agent\",\"read_file\",\"self\",\"probe_environment\",\"unset_api_key\",\"read_config\",\"update_config\"]}"}}');
