INSERT INTO event VALUES(230,6,7,'context.blob',1,1767225830000,'{"payload":{"digest":"6e418fb15040d4b29421ec9a2946acb53ce350ccb8c8fb463b9303d660482e99","value":"{\"description\":\"Read and return workspace files. For text files you can supply an optional line range. PDFs (.pdf) and common image formats are returned as attachments so vision-capable models can inspect their pages or visual content.\",\"name\":\"read_file\",\"parameters\":{\"properties\":{\"path\":{\"description\":\"Workspace-relative or absolute file path to read.\",\"type\":\"string\"},\"range\":{\"anyOf\":[{\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line, inclusive and 1-indexed; the end of the file when omitted.\"},\"start\":{\"description\":\"First line, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"items\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}]}]},\"maxItems\":2,\"minItems\":1,\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Optional inclusive line range to read.\"}},\"required\":[\"path\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(231,6,8,'context.blob',1,1767225831000,'{"payload":{"digest":"ec10868c62c153531d218406d87ce48fcfde705a2d58b4bda0dc1d9d8757d3cf","value":"{\"description\":\"Find files matching glob patterns (e.g., \\\"**/*.md\\\", \\\"src/**/*.ts\\\"). Returns paths sorted by modification time.\",\"name\":\"glob\",\"parameters\":{\"properties\":{\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Directory to search within. Defaults to the workspace root.\"},\"pattern\":{\"description\":\"Glob pattern to match, such as \\\"**/*.md\\\" or \\\"src/**/*.ts\\\".\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"pattern\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(232,6,9,'context.blob',1,1767225832000,'{"payload":{"digest":"1d7f568af14464b5eb9d0dd293f75e264d7cf67e849f073cd683f1a50967b9bd","value":"{\"description\":\"Search file contents using regex patterns. For surrounding lines use -C with output_mode \\\"content\\\".\",\"name\":\"grep\",\"parameters\":{\"properties\":{\"-A\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Lines of context AFTER each match (only with output_mode \\\"content\\\").\"},\"-B\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Lines of context BEFORE each match (only with output_mode \\\"content\\\").\"},\"-C\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Lines of context before AND after each match.\"},\"-i\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Case-insensitive search.\"},\"-n\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Show line numbers.\"},\"glob\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Glob filter for file names (e.g. \\\"*.md\\\").\"},\"head_limit\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Limit to first N results.\"},\"literal\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Exact string, not regex.\"},\"multiline\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Enable multiline matching (pattern can span lines).\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Skip first N results.\"},\"output_mode\":{\"anyOf\":[{\"enum\":[\"content\",\"files_with_matches\",\"count\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Must be \\\"content\\\", \\\"files_with_matches\\\", or \\\"count\\\". For context lines around matches, use -C instead.\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"File or directory to search in.\"},\"pattern\":{\"description\":\"Regex pattern.\",\"minLength\":1,\"type\":\"string\"},\"type\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Ripgrep file type filter (e.g. \\\"md\\\", \\\"py\\\").\"}},\"required\":[\"pattern\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(233,6,10,'context.blob',1,1767225833000,'{"payload":{"digest":"c607cf9bd7fe97fea9e23a46d7b3d3bee54964795a6fa329db90b93962916aa5","value":"{\"description\":\"Read the resources you have now. Takes no arguments and changes nothing.\\n\\nIt answers:\\n- `now`: the current time in this machine''s zone: ISO 8601 with its UTC offset, then the zone''s name in brackets. Every time in the answer is written the same way.\\n- `models`: the models a run can use now, each with `billing` (the subscription plan its next request is paid by, or `api-key:<provider>`) and its listed prices in US dollars per million tokens (input, cached input, output; `aboveInputTokens` when a longer prompt is billed at other rates). A request paid by a plan costs nothing per token; the listed prices are what the provider''s API key is billed.\\n- `plans`: each subscription plan, whether it carries requests now (`on`), and what is known of its quota: each window''s share remaining and when it resets, with `asOf`, when that was learned and from which `source`. A plan''s quota endpoint is asked at most every 30 seconds; a plan whose replies state its quota is known only as of its last reply, which may be long ago. `failed` names why a quota read gave nothing; `unknown` says why nothing is known.\\n- `spend`: what this run has spent in US dollars (`runUsd`), and with every run it started (`treeUsd`), and `caps`: each spend cap this run or a run it belongs to was started with; that run and the runs it started are stopped once their spend reaches `maxCostUsd`.\\n\\nA field that could not be read is replaced by one that says why (`modelsUnknown`, `plansUnknown`).\",\"name\":\"resources\",\"parameters\":{\"properties\":{},\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(234,6,11,'context.blob',1,1767225834000,'{"payload":{"digest":"8a2319aaf4d5a9441e58b42c2cd4eb259778d07d1187cc2cd49bf8e068886675","value":"{\"description\":\"Read or edit your own context: the messages each of your requests sends.\\n\\n- view: each message with its index, role, kind, estimated tokens and a preview; the window size and the tokens in use; and the replacements this response already asked for.\\n- replace: messages [from, to) are replaced, before your next request, by one message holding `with`. Indices are the view''s, as this response was sent; ranges asked for in one response must not overlap. The range ends at or before the response that makes the call, and keeps each tool call with its results.\\n\\nThe replaced messages stay in the stored history: the person still sees them, and the executions tool, where offered, reads them back (/executions/current/conversation). A replacement ends prompt-cache reuse from its first message on, and any provider-side continuation, so the next request pays full input price for everything after that point. Keep what the user asked of you, in substance.\",\"name\":\"context\",\"parameters\":{\"properties\":{\"action\":{\"anyOf\":[{\"enum\":[\"view\",\"replace\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"\\\"view\\\": Read the view (the default).\"},\"from\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index of the first message replaced.\"},\"to\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index after the last message replaced.\"},\"with\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": The text that stands in for those messages.\"}},\"type\":\"object\"}}"}}');
