INSERT INTO event VALUES(293,8,5,'context.blob',1,1767225893000,'{"payload":{"digest":"e652e7c491f1d3e82f47d01a2e49b5ca33b255c304fa106df63cb1edb7ee1b78","value":"{\"sections\":{\"core plugin\":\"For math in responses, use $...$ or \\\\(...\\\\) for inline and $$...$$ or \\\\[...\\\\] for display math. Wrap LaTeX environments like align or gather inside $$...$$ (e.g., $$\\\\begin{align}...\\\\end{align}$$) so they render correctly.\",\"wolfram plugin\":\"Run Wolfram Language through bash with `wolframscript -code ''...''` or `wolframscript -file script.wl`; each run is a fresh session.\"},\"tools\":[\"script\",\"plan\",\"codex\",\"bash\",\"wake\",\"plugin_manager\",\"resources\",\"context\",\"self\",\"probe_environment\",\"unset_api_key\",\"read_config\",\"update_config\"]}"}}');
INSERT INTO event VALUES(294,8,6,'context.blob',1,1767225894000,'{"payload":{"digest":"c5bb1736c72c5e4785e38a76b24a998fe6c04894684679c02b7ea6c80abb30e7","value":{"$b":"8bf55252ebdc341c1e62c4ec19f5215b047492e91620ddd6095f602e90a63fa5"}}}');
INSERT INTO event VALUES(295,8,7,'context.blob',1,1767225895000,'{"payload":{"digest":"b9b1c6c74a51c9f6e2c1fe0d7844330d329fb6f5e0146bc35e6b2e26519b0fc3","value":"{\"description\":\"Propose or replace the plan: `objective` is a plain document stating what to achieve, the intended approach, and a verifiable stopping condition. Where the user''s approval settings ask, the user may approve it, run it as a goal (a goal run then works on it in rounds until it verifies the stopping condition), or reject it; otherwise it is approved as proposed. Propose a new plan only when the objective or approach genuinely changes.\",\"name\":\"plan\",\"parameters\":{\"properties\":{\"objective\":{\"description\":\"The plan document: what to achieve, the intended approach, and a verifiable stopping condition. Plain prose or markdown - no structured steps.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"objective\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(296,8,8,'context.blob',1,1767225896000,'{"payload":{"digest":"d9362d87c2e2a7abe053247649f3a41e0c9a2b06dc02a63b32b890074f9f4996","value":"{\"description\":\"Spin off an OpenAI Codex agent to perform code analysis, generation, or research in a sandboxed environment. The agent runs the Codex CLI locally and can read files, run commands, and make edits within its sandbox, which follows this run''s approval policy: workspace-write when the launch was approved, full access under Auto-approve or an all-agent-work grant. Auth is handled by the CLI itself: use `codex login` (OAuth, recommended) or set OPENAI_API_KEY env var. Always async: returns immediately with a run ID; each turn is delivered back as a follow-up message (including the thread_id). Pass thread_id on a later call to continue that thread with a follow-up instruction, one turn per call. Choose codex for coding tasks that benefit from a separate OpenAI agent. It runs in its own sandbox with independent tool use, async and multi-turn like `agent`. It runs in the working directory of the calling agent and takes no directory argument, so give parallel codex agents disjoint files to edit. codex and claude_code are both independent sandboxed coders distinct from the in-process `agent` specialists. Prefer whichever vendor fits the task.\",\"name\":\"codex\",\"parameters\":{\"properties\":{\"prompt\":{\"description\":\"Instruction for the Codex agent. For a new session, describe the task. For a resume (thread_id set), describe the follow-up.\",\"type\":\"string\"},\"thread_id\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Continue an existing Codex thread with a follow-up instruction, as its next turn. A thread whose turn is still running refuses another until that turn is delivered.\"}},\"required\":[\"prompt\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(297,8,9,'context.blob',1,1767225897000,'{"payload":{"digest":"97e33fc965755d32f598352474eb78e7bcd3bd9090776d9562c09c9bd51fd56f","value":"{\"description\":\"Execute shell commands in the working directory (the project root, or the worktree the run is rooted in). Available environment variables: $PROJECT_DIR (that directory), $PROJECT_NAME (project name). Returns stdout on success, throws error with stderr on failure. Use run_in_background for long-running commands, with `timeout` raised to what they need.\",\"name\":\"bash\",\"parameters\":{\"properties\":{\"command\":{\"type\":\"string\"},\"description\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"A short description of what the command does, in 5-10 words (e.g. \\\"Run the unit tests\\\"). It names the call in the transcript and the background task list; execution ignores it.\"},\"run_in_background\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Run command in background. Returns immediately with run ID and a background task tab. Result delivered as follow-up when complete; `timeout` still bounds the command.\"},\"timeout\":{\"anyOf\":[{\"maximum\":600000,\"minimum\":1000,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Timeout in milliseconds (max 600,000 ms / 10 min, default 120,000 ms / 2 min).\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(298,8,10,'context.blob',1,1767225898000,'{"payload":{"digest":"c7cb7ca529600dfe0965e682c6109f84d037ccd0a2f90fa1d5610c48d136b838","value":"{\"description\":\"Arrange to be continued at a later time, with a note you write to yourself now. The call returns at once; nothing waits. When the time comes the note joins your input, marked as your own note with when you asked for it, when it was due and when it is delivered, and you take a turn from it as you would from a message. What you do then is yours to decide. A repeating job is a wake whose turn arranges the next one.\\n\\nCommands:\\n- `set` (the default) takes `note` and either `afterSeconds` or `at`, at least 60 seconds from now. It answers the wake''s `id` and `due` time. A run holds at most 20 pending wakes.\\n- `list` answers the pending wakes.\\n- `cancel` drops the pending wake `id` names.\\n\\nEvery command answers the pending wakes after it, as `pending`.\\n\\nThe time is kept by the process that holds this project. If none is running when a wake is due, its note is delivered once, late, when one next opens the project. A stop of this run cancels its pending wakes. From a background script the note goes to the conversation the script belongs to. A run that takes no later message (a one-shot run, a program) cannot be continued later, and the call fails.\",\"name\":\"wake\",\"parameters\":{\"properties\":{\"afterSeconds\":{\"anyOf\":[{\"exclusiveMinimum\":0,\"maximum\":9007199254740991,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"set\\\": Seconds from now, at least 60. Give this or `at`.\"},\"at\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"set\\\": A time as ISO 8601 with its UTC offset (`2026-01-01T00:00:01.000Z`, `2030-01-31T09:00:00+01:00`), without the zone name in brackets that times are shown with. Give this or `afterSeconds`.\"},\"command\":{\"anyOf\":[{\"enum\":[\"set\",\"list\",\"cancel\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"\\\"set\\\": Arrange a wake. Default command. | \\\"list\\\": Answer the pending wakes. | \\\"cancel\\\": Drop one pending wake.\"},\"id\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"cancel\\\": The id of the wake to drop, as `set` and `list` answer it.\"},\"note\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"set\\\": What you will read when the time comes. Write it for a reader who remembers nothing of why it was set: what to check or do, and what to do next.\"}},\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(299,8,11,'context.blob',1,1767225899000,'{"payload":{"digest":"2a28b57fff4ee9496c278238dbf33992fc0099f08ed567fd224b59eac182ffb9","value":"{\"description\":\"Manage the plugins you load: list them, install one, and enable, disable or remove one. A plugin is a folder that can carry skills, agents, programs, MCP servers, hooks, and a native module: `harness.mjs` at its root, which runs inside this process and adds tools, services and a section of your instructions. Each call of a native module''s tool asks under the approval policy, as an MCP server''s tool does, whatever the tool declares, and is stopped after 60 seconds; a call that fails ends alone, its error naming the plugin.\\n\\nCommands:\\n- `list` (the default) answers every installed plugin: whether it is enabled, whether it is trusted as it is now, and what it carries.\\n- `install` takes `source`: a plugin folder, a git URL, or github.com/<owner>/<repo>[@ref]. It records the plugin disabled; nothing in it runs.\\n- `enable` takes `name`. Unless the person already trusts the plugin as it is, they are shown what it carries and asked to trust it; once they do, it loads. Any later edit to it withdraws it until it is enabled and trusted again. Enabling a plugin with a native module always asks the person, whatever the approval policy, even one they trusted before and disabled; where no person can be asked, it fails and a person enables it themselves.\\n- `disable` takes `name`: it stays installed and trusted, and loads nothing. The person is asked first.\\n- `remove` takes `name`: it is forgotten with its trust. The person is asked first.\\n\\nA change reaches you at your next step (your next request to the model): its tools are offered, or withdrawn, then. A call already running keeps the version it started with; a call a stopped run left unfinished is not run again on another version when the run resumes: it ends with its outcome unknown, and the version loaded then serves your next step. When a newly trusted version of a native module does not load, the version in use before it stays in use until the plugin is fixed or disabled, but only while this process runs: after a restart the plugin is withheld with the new version''s reason. `list` names the version in use and one that did not load.\\n\\nA plugin folder has `.claude-plugin/plugin.json` (`{ \\\"name\\\": \\\"<name>\\\" }`). Its `harness.mjs` begins with `export const description = ''<one line>'';` and `export const provides = [...];` (each of `tool:<name>`, `program:<name>`, `module:<name>`, `processLayer`, `sessionLayer`, `prompt`), and its default export takes `{ plugins, effect }` (the plugin authoring surface, and the modules of the Effect library this process runs that a plugin is written with: `Effect`, `Context`, `Layer`, `Schema`, `Stream`, `Scope` and their kin) and returns `plugins.definePlugin({ id: ''<name>'', tools: [...] })`, each tool made with `plugins.defineTool`.\",\"name\":\"plugin_manager\",\"parameters\":{\"properties\":{\"command\":{\"anyOf\":[{\"enum\":[\"list\",\"install\",\"enable\",\"disable\",\"remove\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"\\\"list\\\": Answer every installed plugin. Default command. | \\\"install\\\": Install a plugin, disabled. | \\\"enable\\\": Ask the person to trust a plugin, and load it. | \\\"disable\\\": Stop loading a plugin; it stays installed. | \\\"remove\\\": Forget a plugin and the trust given to it.\"},\"name\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"enable\\\", \\\"disable\\\", or \\\"remove\\\": The installed plugin, by the name `list` answers.\"},\"source\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"install\\\": A plugin folder (relative to your working directory), a git URL, or github.com/<owner>/<repo>[@ref].\"}},\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(300,8,12,'context.blob',1,1767225900000,'{"payload":{"digest":"c607cf9bd7fe97fea9e23a46d7b3d3bee54964795a6fa329db90b93962916aa5","value":"{\"description\":\"Read the resources you have now. Takes no arguments and changes nothing.\\n\\nIt answers:\\n- `now`: the current time in this machine''s zone: ISO 8601 with its UTC offset, then the zone''s name in brackets. Every time in the answer is written the same way.\\n- `models`: the models a run can use now, each with `billing` (the subscription plan its next request is paid by, or `api-key:<provider>`) and its listed prices in US dollars per million tokens (input, cached input, output; `aboveInputTokens` when a longer prompt is billed at other rates). A request paid by a plan costs nothing per token; the listed prices are what the provider''s API key is billed.\\n- `plans`: each subscription plan, whether it carries requests now (`on`), and what is known of its quota: each window''s share remaining and when it resets, with `asOf`, when that was learned and from which `source`. A plan''s quota endpoint is asked at most every 30 seconds; a plan whose replies state its quota is known only as of its last reply, which may be long ago. `failed` names why a quota read gave nothing; `unknown` says why nothing is known.\\n- `spend`: what this run has spent in US dollars (`runUsd`), and with every run it started (`treeUsd`), and `caps`: each spend cap this run or a run it belongs to was started with; that run and the runs it started are stopped once their spend reaches `maxCostUsd`.\\n\\nA field that could not be read is replaced by one that says why (`modelsUnknown`, `plansUnknown`).\",\"name\":\"resources\",\"parameters\":{\"properties\":{},\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(301,8,13,'context.blob',1,1767225901000,'{"payload":{"digest":"8a2319aaf4d5a9441e58b42c2cd4eb259778d07d1187cc2cd49bf8e068886675","value":"{\"description\":\"Read or edit your own context: the messages each of your requests sends.\\n\\n- view: each message with its index, role, kind, estimated tokens and a preview; the window size and the tokens in use; and the replacements this response already asked for.\\n- replace: messages [from, to) are replaced, before your next request, by one message holding `with`. Indices are the view''s, as this response was sent; ranges asked for in one response must not overlap. The range ends at or before the response that makes the call, and keeps each tool call with its results.\\n\\nThe replaced messages stay in the stored history: the person still sees them, and the executions tool, where offered, reads them back (/executions/current/conversation). A replacement ends prompt-cache reuse from its first message on, and any provider-side continuation, so the next request pays full input price for everything after that point. Keep what the user asked of you, in substance.\",\"name\":\"context\",\"parameters\":{\"properties\":{\"action\":{\"anyOf\":[{\"enum\":[\"view\",\"replace\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"\\\"view\\\": Read the view (the default).\"},\"from\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index of the first message replaced.\"},\"to\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index after the last message replaced.\"},\"with\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": The text that stands in for those messages.\"}},\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(302,8,14,'context.blob',1,1767225902000,'{"payload":{"digest":"68658b6c4997ca7c56924c7911f8fc962eb09157a11aa139f5bba01ca0caea61","value":"{\"description\":\"Run yourself again on a prompt, as a child of this call, and wait for its result: `{ response, files, structured?, runId, outcome, cost, spent }`, as `agent()` resolves.\\n\\nForked (the default), the child continues this conversation as it stood when the script started (the message of the turn that started it, not that turn''s work so far), with `prompt` added to that message; with `fork: false` it starts with no earlier conversation. Either way the child is told `prompt` is the one part of the script''s work it does, and not to take on the rest. It is you with your tools, and nothing is proposed or approved again. It runs on your model unless `model` names another, which is how a different model checks a result with your prompt and tools; a fork takes only a model that can continue this conversation, and a model with another conversation format takes `fork: false`.\\n\\nIt rejects with an Error named `AgentFailed`, `TimedOut` (past `timeoutMs`), `BudgetExceeded` (the child and the runs it started spent `maxCostUsd` before it finished; the cap is read after each reply, so the spend can pass it by the replies then in flight), `Skipped` (the user stopped it) or `ModelUnavailable`. Call it from a script; called directly, it runs nothing.\",\"name\":\"self\",\"parameters\":{\"properties\":{\"fork\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Continue this conversation as it stood when the script started, with `prompt` added to the message that started it; `false` starts with no earlier conversation. Either way the child is told `prompt` is the one part of the work it does.\"},\"label\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"A short name for the child: its card’s title and its run’s name.\"},\"maxCostUsd\":{\"anyOf\":[{\"exclusiveMinimum\":0,\"type\":\"number\"},{\"type\":\"null\"}],\"description\":\"A spend cap in USD on the child and every run it starts, for as long as the child exists: once they have spent it, they are stopped. A call that waits for the child rejects with `BudgetExceeded`; a background child reports it as its result.\"},\"model\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Model reference, `@effort` suffix allowed (`@low` … `@max`, `@none`). Defaults to your current model when available.\"},\"prompt\":{\"description\":\"What this run of you works on.\",\"minLength\":1,\"type\":\"string\"},\"schema\":{\"anyOf\":[{\"type\":\"object\"},{\"type\":\"null\"}],\"description\":\"A JSON Schema object: the run finishes by submitting a value of it, returned as `structured`.\"},\"timeoutMs\":{\"anyOf\":[{\"maximum\":86400000,\"minimum\":1000,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Stops the child after this many milliseconds: `TimedOut`. Only for a call that waits for its child.\"}},\"required\":[\"prompt\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(303,8,15,'context.blob',1,1767225903000,'{"payload":{"digest":"2865a560c0ec5ccf264a4065cc04cd0c5db06bfce1a3dee8c42747b50de4b99b","value":"{\"description\":\"Probe the active host and environment and return a structured JSON summary covering host kind, OS, shell, PATH, detected package manager (brew/apt/scoop), installation status of TeXRA''s core LaTeX dependencies (pdflatex, latexmk, latexindent, perl, gs, gm/magick, texcount, latexdiff), the LaTeX Workshop VS Code extension, each provider API key''s origin (TeXRA secrets, environment, or absent; values are never returned), ChatGPT subscription state, broader usable credential status, and the rest of TeXRA''s persisted credential store (`storedSecrets`: `staleSecrets`, the stored credential entries that do not count as a saved credential (an `apiKey.*` entry for an unknown provider, or a known provider''s key whose stored value is blank), by raw key name, and a redacted count of other secret names; `\\\"unavailable\\\"` when the store cannot be read). Recognised providers'' keys can be removed with unset_api_key, and other entries only through the current host''s credential-management surface. With {\\\"tool\\\": \\\"<name>\\\"}, re-checks only that tool on PATH and answers in one line (use after an install command to confirm it worked). Read-only, no approval required. Call this first in any setup session to decide what to do next, and again as the final check.\",\"name\":\"probe_environment\",\"parameters\":{\"properties\":{\"tool\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"If provided, re-checks just this one tool on PATH (e.g. \\\"pdflatex\\\") and answers in one line. Otherwise returns the full JSON report.\"}},\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(304,8,16,'context.blob',1,1767225904000,'{"payload":{"digest":"5d318c6d8df6654b5a3419bbc37e69952c5866bec798c7f25d21f01b851c3101","value":"{\"description\":\"Remove a provider''s API key from TeXRA''s persisted credential store. Use when the user wants to rotate or clear credentials. Non-destructive of any other state: just deletes that one secret. If the key is actually coming from a `<PROVIDER>_API_KEY` environment variable, this tool will report that: the credential store has nothing to remove, and the env var must be cleared in the user''s shell.\",\"name\":\"unset_api_key\",\"parameters\":{\"properties\":{\"provider\":{\"description\":\"Provider name to remove the stored key for.\",\"enum\":[\"openai\",\"anthropic\",\"google\",\"xai\",\"deepseek\",\"moonshot\",\"dashscope\",\"minimax\",\"glm\",\"meta\",\"kimiCode\"],\"type\":\"string\"}},\"required\":[\"provider\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(305,8,17,'context.blob',1,1767225905000,'{"payload":{"digest":"90f9ef953de84991d801289cbfef15c6dcecd9d5341d7012fea21b41797fff18","value":"{\"description\":\"Read the effective value of a TeXRA configuration key.\\n\\nAccepts any key starting with `texra.`. Returns the current resolved value (workspace value if set, else user, else default). Use this when teaching the user what a setting controls: read first, explain, then propose a change with `update_config`.\",\"name\":\"read_config\",\"parameters\":{\"properties\":{\"key\":{\"description\":\"Configuration key starting with \\\"texra.\\\" (e.g. texra.bib.defaultPath).\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"key\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(306,8,18,'context.blob',1,1767225906000,'{"payload":{"digest":"b0a24bb323959b7c3411a55041dac90edc953a451cc534d03507a4a6e0963db6","value":"{\"description\":\"Update a TeXRA configuration value (allowlisted keys only).\\n\\nUse this AFTER calling `read_config` and explaining to the user what the setting does and what the new value will mean. Explain every change clearly. Pass `target: \\\"workspace\\\"` only when the change is genuinely workspace-specific (e.g. a project-local bib path); default to `\\\"user\\\"` for general preferences shared across workspaces.\\n\\nAllowlisted keys:\\n- `texra.bib.defaultPath`\\n- `texra.audio.soxPath`\\n- `texra.latex.tikzInputDirectory`\\n- `texra.maxImageDimension`\\n\\nAnything outside this list must be changed through the host''s regular configuration surface.\",\"name\":\"update_config\",\"parameters\":{\"properties\":{\"key\":{\"description\":\"Configuration key to update. Must be on the setup allowlist:\\n- `texra.bib.defaultPath`\\n- `texra.audio.soxPath`\\n- `texra.latex.tikzInputDirectory`\\n- `texra.maxImageDimension`\",\"enum\":[\"texra.bib.defaultPath\",\"texra.audio.soxPath\",\"texra.latex.tikzInputDirectory\",\"texra.maxImageDimension\"],\"type\":\"string\"},\"target\":{\"anyOf\":[{\"enum\":[\"user\",\"workspace\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"\\\"user\\\" updates the global setting shared across workspaces; \\\"workspace\\\" scopes the change to the current workspace only.\"},\"value\":{}},\"required\":[\"key\",\"value\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(307,8,19,'context.blob',1,1767225907000,'{"payload":{"digest":"9cdc6a417d619dc20a1f804fb60cd44ecb306ec096037384b3b739f92ffce260","value":{"$b":"dcbe6ffd2f57f1134b7c887f5ce3ef3655edf54dbf45989754d919f32ca07511"}}}');
INSERT INTO event VALUES(308,8,20,'context.blob',1,1767225908000,'{"payload":{"digest":"7a5d27e235e3f9b1f30135e6eb9518f2872302bb2ef007f302834e08acae995f","value":{"$b":"e6ccf5ca95ebef9caddd9099c2f5f7af7ce802a55dac4b30008dfeb7467a84b4"}}}');
INSERT INTO event VALUES(309,8,21,'context.blob',1,1767225909000,'{"payload":{"digest":"dd44db81912b241a84b811cbecfc7789e089eb1375f36a1f2a26d3cf2c6af9a1","value":"\"import { leanCheck, rounds, statedAxioms } from ''builtIn:rounds'';\\n\\nconst PROVER = [\\n  ''You complete formal proofs in a Lean 4 project. Work out the mathematics first: understand each statement, find the argument, and write a short informal outline before you write tactics.'',\\n  ''Find what the library already has before you prove it yourself: lean_loogle searches Mathlib by type signature or name pattern (it takes several queries at once), and when the project has a .lake/packages directory, grep and glob read Mathlib and the other dependencies directly.'',\\n  ''Write a proof, then check the file, and repeat until Lean reports no error and no declaration that uses sorry. Lean reads a file only when it opens it, so after every edit call lean_file on the file before lean_diagnostics; otherwise the diagnostics describe the file as it was. lean_inspect shows the goal at a position. Do not leave sorry, admit or a new axiom in place of a proof.'',\\n  \\\"Keep every statement as it is: change a theorem''s hypotheses or conclusion only when the instruction asks, and say so in your answer when a statement is false as written. Keep the project''s names and conventions, and when its AGENTS.md lists tactics or automation, use them.\\\",\\n  ''Read a file before you edit it. Your answer goes to the person who started the program: say what you proved and how, in a few sentences with the mathematics in $...$, and name anything you could not finish.'',\\n].join(''\\\\n\\\\n'');\\n\\nexport default async (args, launch) => {\\n  const stated = await statedAxioms(launch.inputFiles);\\n  return rounds(\\n    {\\n      name: ''prove'',\\n      system: PROVER,\\n      tools: [\\n        ''read_file'',\\n        ''write_file'',\\n        ''edit_file'',\\n        ''glob'',\\n        ''grep'',\\n        ''bash'',\\n        ''lean_diagnostics'',\\n        ''lean_inspect'',\\n        ''lean_file'',\\n        ''lean_project'',\\n        ''lean_loogle'',\\n      ],\\n      rounds: 3,\\n      extension: ''.lean'',\\n      describes: ''the .lean files to complete'',\\n      fallback:\\n        ''Complete every proof in these files: replace each sorry with a proof and fix every error.'',\\n      check: leanCheck(stated),\\n    },\\n    launch,\\n  );\\n};\\n\""}}');
INSERT INTO event VALUES(310,8,22,'context.blob',1,1767225910000,'{"payload":{"digest":"a6ca2ee1de6b99808ba532e1e6d14e44eab626843d1691ef6a703112bf4d67dd","value":"\"/**\\n * The `lean-simplify` program: rounds of a child agent that bring Lean\\n * files toward library quality without changing what they prove, until Lean\\n * reports them clean and they declare no new axiom (`builtIn:rounds`).\\n */\\nimport { leanCheck, rounds, statedAxioms } from ''builtIn:rounds'';\\n\\nconst SIMPLIFIER = [\\n  ''You refactor Lean 4 files toward Mathlib quality: clear, general, well named and consistent with the library. Never change what a declaration states or computes, only how it is written; every theorem statement, instance and value stays as it is.'',\\n  \\\"Read the files and the project''s AGENTS.md first, and use the tactics and automation it lists. Then work in this order: naming and style (Mathlib''s compositional names, 100-character lines, docstrings on public declarations, minimal imports, scoped opens), generality (the weakest typeclass the proof needs, `@[to_additive]` instead of parallel copies), proof simplification (explicit simp sets, `omega`, `gcongr`, `positivity`, `norm_num`, `ring`, a `calc` where it shows the structure), and duplication (a helper lemma, or the Mathlib lemma that already exists: search with lean_loogle and grep before you keep a hand-written one).\\\",\\n  ''Make one logical change per edit. After every edit call lean_file on the file, then lean_diagnostics, and undo an edit that introduces an error; no sorry, admit or new axiom. Keep comments that explain the mathematics and readable proofs that a shorter tactic would hide. When the project pairs the Lean files with LaTeX notes, report where a statement, a definition or a proof outline disagrees with them, but change only the Lean side.'',\\n  ''Your answer goes to the person who started the program: what you changed and why, in a few sentences, and anything you left as it was.'',\\n].join(''\\\\n\\\\n'');\\n\\nexport default async (args, launch) => {\\n  const stated = await statedAxioms(launch.inputFiles);\\n  return rounds(\\n    {\\n      name: ''lean-simplify'',\\n      system: SIMPLIFIER,\\n      tools: [\\n        ''read_file'',\\n        ''edit_file'',\\n        ''glob'',\\n        ''grep'',\\n        ''bash'',\\n        ''lean_diagnostics'',\\n        ''lean_inspect'',\\n        ''lean_file'',\\n        ''lean_project'',\\n        ''lean_loogle'',\\n      ],\\n      rounds: 2,\\n      extension: ''.lean'',\\n      describes: ''the .lean files to simplify'',\\n      fallback:\\n        ''Simplify these files toward Mathlib quality without changing what they prove.'',\\n      check: leanCheck(stated),\\n    },\\n    launch,\\n  );\\n};\\n\""}}');
INSERT INTO event VALUES(311,8,23,'context.blob',1,1767225911000,'{"payload":{"digest":"e08ed09648af9cfdcdd83c1b64e04126b6407848ae2312d1a21c7e674f204f20","value":"\"import { rounds } from ''builtIn:rounds'';\\n\\nconst WRITER = [\\n  \\\"You write and maintain formalization blueprints: LaTeX documents, built with the leanblueprint package and its CLI, that split a proof into small statements with explicit dependencies and link each to its Lean declaration. Follow the package''s own macros and the file layout leanblueprint new creates; invent no parallel conventions.\\\",\\n  ''The macros. Inside a definition, lemma, proposition, theorem or corollary, each with a \\\\\\\\label: \\\\\\\\lean{Name.decl} links Lean declarations (comma-separated), \\\\\\\\leanok marks the statement formalized, \\\\\\\\mathlibok marks it in Mathlib, \\\\\\\\uses{label, ...} lists the statements it depends on, and \\\\\\\\notready marks one that needs more blueprint work. Inside a proof: \\\\\\\\uses{...} for what the proof relies on, \\\\\\\\leanok when the proof is formalized, and \\\\\\\\proves{label} for a proof separated from its statement.'',\\n  ''Write the mathematics as a paper does, in standard notation: no Lean syntax, identifiers or type signatures in the prose. A Lean predicate becomes a sentence, a typeclass assumption becomes \\\"let G be a group\\\", a type becomes the set it stands for. \\\\\\\\lean{} is the only place a Lean name appears. Refer to statements by \\\\\\\\ref to their labels, never by number. Each statement states its hypotheses in full; a proof sketch gives the strategy in a sentence or two, enough for a formalizer to follow.'',\\n  \\\"To write a new blueprint, survey the Lean project first, then design the dependency graph backward from the main results: each node one well-defined fact. To bring an existing one up to date, check every \\\\\\\\lean name against the source (renamed or removed declarations), every \\\\\\\\leanok against lean_diagnostics (no error, no sorry; call lean_file on a Lean file first, since Lean reads a file only when it opens it), every statement against its declaration''s type (lean_inspect hover), and every \\\\\\\\uses against what the proof actually relies on; add entries for significant declarations the blueprint lacks. Before you answer, run leanblueprint web and leanblueprint checkdecls and fix what they report: the program checks your work with the same two commands.\\\",\\n  ''Your answer goes to the person who started the program: what you wrote or changed, what is out of sync or mathematically suspect, and what you left for them.'',\\n].join(''\\\\n\\\\n'');\\n\\n/** What leanblueprint itself checks: the blueprint builds, and every\\n *  \\\\lean name is a declaration of the built project. */\\nconst CHECK = ''leanblueprint web && leanblueprint checkdecls'';\\n\\nexport default async (args, launch) => {\\n  // A missing CLI fails the launch before any round is paid for.\\n  try {\\n    await tools.bash({ command: ''leanblueprint --version'' });\\n  } catch {\\n    throw new Error(\\n      ''blueprint checks its work with the leanblueprint CLI, which is not installed: pip install leanblueprint.'',\\n    );\\n  }\\n  return rounds(\\n    {\\n      name: ''blueprint'',\\n      system: WRITER,\\n      tools: [\\n        ''read_file'',\\n        ''write_file'',\\n        ''edit_file'',\\n        ''glob'',\\n        ''grep'',\\n        ''bash'',\\n        ''lean_diagnostics'',\\n        ''lean_inspect'',\\n        ''lean_file'',\\n        ''lean_loogle'',\\n        ''web_search'',\\n        ''web_fetch'',\\n      ],\\n      rounds: 2,\\n      extension: ''.tex'',\\n      describes:\\n        \\\"the blueprint''s .tex files (a project without one starts with leanblueprint new)\\\",\\n      fallback: ''Bring this blueprint up to date with the Lean project.'',\\n      check: async () => {\\n        try {\\n          await tools.bash({ command: CHECK, timeout: 600000 });\\n          return {\\n            clean: true,\\n            report:\\n              ''The blueprint builds, and leanblueprint checkdecls finds every \\\\\\\\lean declaration.'',\\n          };\\n        } catch (failure) {\\n          return {\\n            clean: false,\\n            report: CHECK + '' failed:\\\\n'' + failure.message,\\n          };\\n        }\\n      },\\n    },\\n    launch,\\n  );\\n};\\n\""}}');
INSERT INTO event VALUES(312,8,24,'context.blob',1,1767225912000,'{"payload":{"digest":"9e6a58c54ce207ed0bc4403666ed10a659608612f8a0a26d9a965b8d2752e602","value":"\"/**\\n * The `lean-search` program: one child agent that finds what Mathlib and\\n * the project already have for a statement, an API or a formalization\\n * question, and says what it found and what is missing. The launch''s\\n * instruction and files are the child''s prompt.\\n */\\n\\nconst system = [\\n  ''You find what already exists before anyone formalizes it: lemmas in Mathlib and the Lean project, the API around a definition, the tactic for a goal, and the paper behind a result. Search several sources before you conclude that something does not exist.'',\\n  ''lean_loogle searches Mathlib by type signature, name pattern, subexpression or conclusion, several queries at once; try more than one formulation (arguments swapped, `↔` against `→`). When the project has .lake/packages, grep and glob read Mathlib and the other dependencies directly, which is faster for an exact name and shows the proofs around it. lean_inspect shows the type of an identifier or the goal at a position in the project, lean_diagnostics what a file reports (call lean_file first, since Lean reads a file only when it opens it). web_search and web_fetch reach the Lean and Mathlib documentation and the community discussion, and the papers on arXiv.'',\\n  ''Answer with what you found, in three groups: an exact match, a close match that needs adapting, and what is genuinely missing. Give each match its full name, its type and its import. For something missing, propose the most general statement, the Mathlib file it belongs in and the name its naming conventions give it. Say which queries and sources you tried.'',\\n  ''Do not change the project: write a file only when the instruction asks for a draft.'',\\n].join(''\\\\n\\\\n'');\\n\\nconst tools = [\\n  ''read_file'',\\n  ''write_file'',\\n  ''glob'',\\n  ''grep'',\\n  ''bash'',\\n  ''lean_diagnostics'',\\n  ''lean_file'',\\n  ''lean_inspect'',\\n  ''lean_loogle'',\\n  ''web_search'',\\n  ''web_fetch'',\\n];\\n\\nexport default async (\\n  args,\\n  { instruction, inputFiles, contextFiles, mediaFiles },\\n) => {\\n  if (!instruction.trim() && inputFiles.length === 0 && mediaFiles.length === 0)\\n    throw new Error(\\n      ''lean-search needs an instruction, inputFiles or mediaFiles.'',\\n    );\\n  const prompt = [\\n    ...(instruction.trim()\\n      ? [''<instruction>\\\\n'' + instruction.trim() + ''\\\\n</instruction>'']\\n      : []),\\n    ...(inputFiles.length > 0\\n      ? [''The files: '' + inputFiles.join('', '') + ''.'']\\n      : []),\\n    ...(mediaFiles.length > 0\\n      ? [''Attached: '' + mediaFiles.join('', '') + ''.'']\\n      : []),\\n    ...(contextFiles.length > 0\\n      ? [\\n          ''Read these for context and do not change them: '' +\\n            contextFiles.join('', '') +\\n            ''.'',\\n        ]\\n      : []),\\n  ].join(''\\\\n\\\\n'');\\n  const reply = await agent(prompt, {\\n    system,\\n    tools,\\n    mediaFiles,\\n    label: ''lean-search'',\\n    id: ''lean-search'',\\n  });\\n  return reply.response;\\n};\\n\""}}');
INSERT INTO event VALUES(313,8,25,'context.blob',1,1767225913000,'{"payload":{"digest":"868d3307b6df0155325713fee6708a6e00b40317ae303f19885ac19344e20a74","value":{"$b":"d8a79cba8232a77e1b24649af61c307c1528b6568df2a28858a70612e25c04d5"}}}');
INSERT INTO event VALUES(314,8,26,'context.blob',1,1767225914000,'{"payload":{"digest":"10b0279de984c44f71aec770c9ebf2a4b46dbfd454810e8b2e085d57dbfac7ec","value":"\"/**\\n * The program `transcribe`: one child, with the launch''s media attached to\\n * its prompt, writes their content as a LaTeX file in the project with its\\n * file tools.\\n */\\n\\nconst TRANSCRIBER = [\\n  ''You turn attached media into LaTeX. Images of handwriting or scans are pages of one text, in the order given: you write their content in the notation and style of the context files. Recordings are one session, in the order given: you transcribe the spoken words with speakers and timestamps, a short opening summary and logical sections, and write spoken mathematics as LaTeX equations.'',\\n  ''Write one LaTeX document that compiles on its own, as a new file in the project: the file the instruction names, or transcript.tex. Never overwrite a file that exists: check first, and when the name is taken choose a free one (transcript-2.tex) and say so. For images, use the document class, notation, environments and symbols of the context files when there are any. For a recording, open with a short summary of the topics, then write each utterance as \\\"[HH:MM:SS] Speaker: text\\\", grouped into sections; do not use markdown.'',\\n  \\\"Then review your transcription against the media and correct the file. For images, fix symbols you misread or that differ from the context files'' notation, subscripts and superscripts, and environments. For a recording, fix misheard words, speaker labels, timestamps and equations. When latexmk is installed, compile the file and fix what the log reports.\\\",\\n  ''Your answer goes to the person who started the program: the file you wrote, and what you could not read or hear.'',\\n].join(''\\\\n\\\\n'');\\n\\nexport default async (\\n  args,\\n  { instruction, inputFiles, contextFiles, mediaFiles },\\n) => {\\n  if (mediaFiles.length === 0)\\n    throw new Error(\\n      ''transcribe works on media: pass the images, scans or recordings as mediaFiles.'',\\n    );\\n  const context = [...inputFiles, ...contextFiles];\\n  const reply = await agent(\\n    [\\n      ...(instruction.trim()\\n        ? [''<instruction>\\\\n'' + instruction.trim() + ''\\\\n</instruction>'']\\n        : []),\\n      ''Transcribe the attached media: '' + mediaFiles.join('', '') + ''.'',\\n      ...(context.length > 0\\n        ? [\\n            ''Read these for notation and style and do not change them: '' +\\n              context.join('', '') +\\n              ''.'',\\n          ]\\n        : []),\\n    ].join(''\\\\n\\\\n''),\\n    {\\n      system: TRANSCRIBER,\\n      tools: [''read_file'', ''write_file'', ''edit_file'', ''glob'', ''grep'', ''bash''],\\n      mediaFiles,\\n      label: ''Transcription'',\\n    },\\n  );\\n  return reply.response;\\n};\\n\""}}');
