INSERT INTO event VALUES(377,10,3,'model.message',2,1767225977000,'{"payload":{"kind":"append","messages":[{"role":"user","content":[{"kind":"text","text":"A script of yours started this run of you with self(). It does one part of the work that script is carrying out, the task below. Do only that task, without taking on the rest of the work or starting further self() runs for it, and end with its result.\n\n<task>\n<goal_judge>\nDecide whether the objective below is met, as things stand now.\n- You did not do this work. The report below, if any, is the claim of whoever did: a claim, not evidence.\n- Derive the requirements from the objective itself, and submit one claim per requirement.\n- Each claim names a check someone else can run again and quotes what it showed.\n- What you could not check is `unverified`, never `verified`.\n- Do not change the work under judgment; scratch files for a check are fine.\nHow you check, and how deep, is yours to decide.\n</goal_judge>\n\n<objective>\nAnswer the golden chat, then stop.\n</objective>\n\n<report>\nThe golden chat is answered.\n</report>\n</task>"}]}],"sourceResponse":null,"input":{"system":"e9ce9e523d6ed8e9d87e28937520990afce108d8c12063e845ea29c1edc68fd2"}}}');
INSERT INTO event VALUES(378,10,4,'context.blob',1,1767225978000,'{"payload":{"digest":"e9ce9e523d6ed8e9d87e28937520990afce108d8c12063e845ea29c1edc68fd2","value":"\"GOLDEN-CHAT: plan, run the plan as a goal, complete it.\\n\\n<workspace_info>\\nWorkspace: /golden/project\\nPlatform: golden\\nShell: golden\\nDate: 2026-01-01\\nGit: this workspace is not a git work tree, or git could not be checked; confirm a repository exists before running git history or status checks.\\n</workspace_info>\""}}');
INSERT INTO event VALUES(379,10,5,'context.blob',1,1767225979000,'{"payload":{"digest":"57e50a6b5e949a36e96a46e432e0c3ebb8eda538bca6c96666b0607780f43b47","value":"\"GOLDEN-CHAT: plan, run the plan as a goal, complete it.\\n\\n<workspace_info>\\nWorkspace: /golden/project\\nPlatform: golden\\nShell: golden\\nDate: 2026-01-01\\nGit: this workspace is not a git work tree, or git could not be checked; confirm a repository exists before running git history or status checks.\\n</workspace_info>\\nFor math in responses, use $...$ or \\\\(...\\\\) for inline and $$...$$ or \\\\[...\\\\] for display math. Wrap LaTeX environments like align or gather inside $$...$$ (e.g., $$\\\\begin{align}...\\\\end{align}$$) so they render correctly.\\nRun Wolfram Language through bash with `wolframscript -code ''...''` or `wolframscript -file script.wl`; each run is a fresh session.\""}}');
INSERT INTO event VALUES(380,10,6,'context.blob',1,1767225980000,'{"payload":{"digest":"97d568e7b567fb0535ee524b79704fbb4654d165b9d619c581dfd98df581da05","value":"{\"sections\":{\"core plugin\":\"For math in responses, use $...$ or \\\\(...\\\\) for inline and $$...$$ or \\\\[...\\\\] for display math. Wrap LaTeX environments like align or gather inside $$...$$ (e.g., $$\\\\begin{align}...\\\\end{align}$$) so they render correctly.\",\"wolfram plugin\":\"Run Wolfram Language through bash with `wolframscript -code ''...''` or `wolframscript -file script.wl`; each run is a fresh session.\"},\"tools\":[\"plan\",\"codex\",\"bash\",\"wake\",\"plugin_manager\",\"resources\",\"context\",\"submit_output\"]}"}}');
INSERT INTO event VALUES(381,10,7,'context.blob',1,1767225981000,'{"payload":{"digest":"b9b1c6c74a51c9f6e2c1fe0d7844330d329fb6f5e0146bc35e6b2e26519b0fc3","value":"{\"description\":\"Propose or replace the plan: `objective` is a plain document stating what to achieve, the intended approach, and a verifiable stopping condition. Where the user''s approval settings ask, the user may approve it, run it as a goal (a goal run then works on it in rounds until it verifies the stopping condition), or reject it; otherwise it is approved as proposed. Propose a new plan only when the objective or approach genuinely changes.\",\"name\":\"plan\",\"parameters\":{\"properties\":{\"objective\":{\"description\":\"The plan document: what to achieve, the intended approach, and a verifiable stopping condition. Plain prose or markdown - no structured steps.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"objective\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(382,10,8,'context.blob',1,1767225982000,'{"payload":{"digest":"d9362d87c2e2a7abe053247649f3a41e0c9a2b06dc02a63b32b890074f9f4996","value":"{\"description\":\"Spin off an OpenAI Codex agent to perform code analysis, generation, or research in a sandboxed environment. The agent runs the Codex CLI locally and can read files, run commands, and make edits within its sandbox, which follows this run''s approval policy: workspace-write when the launch was approved, full access under Auto-approve or an all-agent-work grant. Auth is handled by the CLI itself: use `codex login` (OAuth, recommended) or set OPENAI_API_KEY env var. Always async: returns immediately with a run ID; each turn is delivered back as a follow-up message (including the thread_id). Pass thread_id on a later call to continue that thread with a follow-up instruction, one turn per call. Choose codex for coding tasks that benefit from a separate OpenAI agent. It runs in its own sandbox with independent tool use, async and multi-turn like `agent`. It runs in the working directory of the calling agent and takes no directory argument, so give parallel codex agents disjoint files to edit. codex and claude_code are both independent sandboxed coders distinct from the in-process `agent` specialists. Prefer whichever vendor fits the task.\",\"name\":\"codex\",\"parameters\":{\"properties\":{\"prompt\":{\"description\":\"Instruction for the Codex agent. For a new session, describe the task. For a resume (thread_id set), describe the follow-up.\",\"type\":\"string\"},\"thread_id\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Continue an existing Codex thread with a follow-up instruction, as its next turn. A thread whose turn is still running refuses another until that turn is delivered.\"}},\"required\":[\"prompt\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(383,10,9,'context.blob',1,1767225983000,'{"payload":{"digest":"97e33fc965755d32f598352474eb78e7bcd3bd9090776d9562c09c9bd51fd56f","value":"{\"description\":\"Execute shell commands in the working directory (the project root, or the worktree the run is rooted in). Available environment variables: $PROJECT_DIR (that directory), $PROJECT_NAME (project name). Returns stdout on success, throws error with stderr on failure. Use run_in_background for long-running commands, with `timeout` raised to what they need.\",\"name\":\"bash\",\"parameters\":{\"properties\":{\"command\":{\"type\":\"string\"},\"description\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"A short description of what the command does, in 5-10 words (e.g. \\\"Run the unit tests\\\"). It names the call in the transcript and the background task list; execution ignores it.\"},\"run_in_background\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Run command in background. Returns immediately with run ID and a background task tab. Result delivered as follow-up when complete; `timeout` still bounds the command.\"},\"timeout\":{\"anyOf\":[{\"maximum\":600000,\"minimum\":1000,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Timeout in milliseconds (max 600,000 ms / 10 min, default 120,000 ms / 2 min).\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(384,10,10,'context.blob',1,1767225984000,'{"payload":{"digest":"c7cb7ca529600dfe0965e682c6109f84d037ccd0a2f90fa1d5610c48d136b838","value":"{\"description\":\"Arrange to be continued at a later time, with a note you write to yourself now. The call returns at once; nothing waits. When the time comes the note joins your input, marked as your own note with when you asked for it, when it was due and when it is delivered, and you take a turn from it as you would from a message. What you do then is yours to decide. A repeating job is a wake whose turn arranges the next one.\\n\\nCommands:\\n- `set` (the default) takes `note` and either `afterSeconds` or `at`, at least 60 seconds from now. It answers the wake''s `id` and `due` time. A run holds at most 20 pending wakes.\\n- `list` answers the pending wakes.\\n- `cancel` drops the pending wake `id` names.\\n\\nEvery command answers the pending wakes after it, as `pending`.\\n\\nThe time is kept by the process that holds this project. If none is running when a wake is due, its note is delivered once, late, when one next opens the project. A stop of this run cancels its pending wakes. From a background script the note goes to the conversation the script belongs to. A run that takes no later message (a one-shot run, a program) cannot be continued later, and the call fails.\",\"name\":\"wake\",\"parameters\":{\"properties\":{\"afterSeconds\":{\"anyOf\":[{\"exclusiveMinimum\":0,\"maximum\":9007199254740991,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"set\\\": Seconds from now, at least 60. Give this or `at`.\"},\"at\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"set\\\": A time as ISO 8601 with its UTC offset (`2026-01-01T00:00:01.000Z`, `2030-01-31T09:00:00+01:00`), without the zone name in brackets that times are shown with. Give this or `afterSeconds`.\"},\"command\":{\"anyOf\":[{\"enum\":[\"set\",\"list\",\"cancel\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"\\\"set\\\": Arrange a wake. Default command. | \\\"list\\\": Answer the pending wakes. | \\\"cancel\\\": Drop one pending wake.\"},\"id\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"cancel\\\": The id of the wake to drop, as `set` and `list` answer it.\"},\"note\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"set\\\": What you will read when the time comes. Write it for a reader who remembers nothing of why it was set: what to check or do, and what to do next.\"}},\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(385,10,11,'context.blob',1,1767225985000,'{"payload":{"digest":"2a28b57fff4ee9496c278238dbf33992fc0099f08ed567fd224b59eac182ffb9","value":"{\"description\":\"Manage the plugins you load: list them, install one, and enable, disable or remove one. A plugin is a folder that can carry skills, agents, programs, MCP servers, hooks, and a native module: `harness.mjs` at its root, which runs inside this process and adds tools, services and a section of your instructions. Each call of a native module''s tool asks under the approval policy, as an MCP server''s tool does, whatever the tool declares, and is stopped after 60 seconds; a call that fails ends alone, its error naming the plugin.\\n\\nCommands:\\n- `list` (the default) answers every installed plugin: whether it is enabled, whether it is trusted as it is now, and what it carries.\\n- `install` takes `source`: a plugin folder, a git URL, or github.com/<owner>/<repo>[@ref]. It records the plugin disabled; nothing in it runs.\\n- `enable` takes `name`. Unless the person already trusts the plugin as it is, they are shown what it carries and asked to trust it; once they do, it loads. Any later edit to it withdraws it until it is enabled and trusted again. Enabling a plugin with a native module always asks the person, whatever the approval policy, even one they trusted before and disabled; where no person can be asked, it fails and a person enables it themselves.\\n- `disable` takes `name`: it stays installed and trusted, and loads nothing. The person is asked first.\\n- `remove` takes `name`: it is forgotten with its trust. The person is asked first.\\n\\nA change reaches you at your next step (your next request to the model): its tools are offered, or withdrawn, then. A call already running keeps the version it started with; a call a stopped run left unfinished is not run again on another version when the run resumes: it ends with its outcome unknown, and the version loaded then serves your next step. When a newly trusted version of a native module does not load, the version in use before it stays in use until the plugin is fixed or disabled, but only while this process runs: after a restart the plugin is withheld with the new version''s reason. `list` names the version in use and one that did not load.\\n\\nA plugin folder has `.claude-plugin/plugin.json` (`{ \\\"name\\\": \\\"<name>\\\" }`). Its `harness.mjs` begins with `export const description = ''<one line>'';` and `export const provides = [...];` (each of `tool:<name>`, `program:<name>`, `module:<name>`, `processLayer`, `sessionLayer`, `prompt`), and its default export takes `{ plugins, effect }` (the plugin authoring surface, and the modules of the Effect library this process runs that a plugin is written with: `Effect`, `Context`, `Layer`, `Schema`, `Stream`, `Scope` and their kin) and returns `plugins.definePlugin({ id: ''<name>'', tools: [...] })`, each tool made with `plugins.defineTool`.\",\"name\":\"plugin_manager\",\"parameters\":{\"properties\":{\"command\":{\"anyOf\":[{\"enum\":[\"list\",\"install\",\"enable\",\"disable\",\"remove\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"\\\"list\\\": Answer every installed plugin. Default command. | \\\"install\\\": Install a plugin, disabled. | \\\"enable\\\": Ask the person to trust a plugin, and load it. | \\\"disable\\\": Stop loading a plugin; it stays installed. | \\\"remove\\\": Forget a plugin and the trust given to it.\"},\"name\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"enable\\\", \\\"disable\\\", or \\\"remove\\\": The installed plugin, by the name `list` answers.\"},\"source\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"install\\\": A plugin folder (relative to your working directory), a git URL, or github.com/<owner>/<repo>[@ref].\"}},\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(386,10,12,'context.blob',1,1767225986000,'{"payload":{"digest":"c607cf9bd7fe97fea9e23a46d7b3d3bee54964795a6fa329db90b93962916aa5","value":"{\"description\":\"Read the resources you have now. Takes no arguments and changes nothing.\\n\\nIt answers:\\n- `now`: the current time in this machine''s zone: ISO 8601 with its UTC offset, then the zone''s name in brackets. Every time in the answer is written the same way.\\n- `models`: the models a run can use now, each with `billing` (the subscription plan its next request is paid by, or `api-key:<provider>`) and its listed prices in US dollars per million tokens (input, cached input, output; `aboveInputTokens` when a longer prompt is billed at other rates). A request paid by a plan costs nothing per token; the listed prices are what the provider''s API key is billed.\\n- `plans`: each subscription plan, whether it carries requests now (`on`), and what is known of its quota: each window''s share remaining and when it resets, with `asOf`, when that was learned and from which `source`. A plan''s quota endpoint is asked at most every 30 seconds; a plan whose replies state its quota is known only as of its last reply, which may be long ago. `failed` names why a quota read gave nothing; `unknown` says why nothing is known.\\n- `spend`: what this run has spent in US dollars (`runUsd`), and with every run it started (`treeUsd`), and `caps`: each spend cap this run or a run it belongs to was started with; that run and the runs it started are stopped once their spend reaches `maxCostUsd`.\\n\\nA field that could not be read is replaced by one that says why (`modelsUnknown`, `plansUnknown`).\",\"name\":\"resources\",\"parameters\":{\"properties\":{},\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(387,10,13,'context.blob',1,1767225987000,'{"payload":{"digest":"8a2319aaf4d5a9441e58b42c2cd4eb259778d07d1187cc2cd49bf8e068886675","value":"{\"description\":\"Read or edit your own context: the messages each of your requests sends.\\n\\n- view: each message with its index, role, kind, estimated tokens and a preview; the window size and the tokens in use; and the replacements this response already asked for.\\n- replace: messages [from, to) are replaced, before your next request, by one message holding `with`. Indices are the view''s, as this response was sent; ranges asked for in one response must not overlap. The range ends at or before the response that makes the call, and keeps each tool call with its results.\\n\\nThe replaced messages stay in the stored history: the person still sees them, and the executions tool, where offered, reads them back (/executions/current/conversation). A replacement ends prompt-cache reuse from its first message on, and any provider-side continuation, so the next request pays full input price for everything after that point. Keep what the user asked of you, in substance.\",\"name\":\"context\",\"parameters\":{\"properties\":{\"action\":{\"anyOf\":[{\"enum\":[\"view\",\"replace\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"\\\"view\\\": Read the view (the default).\"},\"from\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index of the first message replaced.\"},\"to\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index after the last message replaced.\"},\"with\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": The text that stands in for those messages.\"}},\"type\":\"object\"}}"}}');
