INSERT INTO event VALUES(688,17,20,'model.message',2,1767226288000,'{"payload":{"kind":"response","responseId":"00000000-0000-4000-8000-000000000079","invocation":{"invocationId":"00000000-0000-4000-8000-000000000077","attempt":1},"turn":{"providerResponseId":"validation-response-1","requestedOrigin":{"protocol":"openai-responses","requestedModel":"gpt-5.6-sol","deployment":{"endpoint":"https://validation.invalid/v1","credentialScope":"validation"},"codecVersion":1},"returnedModel":"gpt-5.6-sol","content":[{"kind":"message","content":[{"kind":"text","text":"Child result."}]}],"finishReason":"stop","usage":{"inputTokens":1,"outputTokens":1,"totalTokens":2,"cachedInputTokens":null,"cacheWriteTokens":null,"reasoningTokens":null,"toolUsePromptTokens":null}},"calls":[],"usage":{"inputTokens":1,"outputTokens":1,"cost":0.000024,"usageRoute":"api-key","responseTimeMs":0,"provider":"openai-responses"}}}');
