INSERT INTO event VALUES(694,17,26,'run.report',1,1767226294000,'{"report":"<subagent-result id=\"a00000000011\" agent=\"golden_child\" status=\"completed\">\n<wall-time>0s</wall-time>\n<working-directory>/golden/project</working-directory>\n<response>\nChild result.\n</response>\n</subagent-result>"}');
INSERT INTO event VALUES(695,18,1,'run.start',2,1767226295000,'{"identity":{"kind":"agent","agent":"golden_script"},"takesFollowUps":true,"worktree":{"workingDirectory":"/golden/project"},"parent":null,"provenance":null,"grants":{"own":{"bash":"on","toolEdit":"on","superYolo":"on"},"goal":[]},"maxCostUsd":null}');
